from itertools import combinations

# Part 1: player counts. Four distinct positive integers summing to 12,
# where one equals the product of two others.
nums = []
for c in combinations(range(1, 12), 4):
    if sum(c) != 12:
        continue
    ok = any(
        c[k] == c[i] * c[j]
        for k in range(4)
        for i in range(4)
        for j in range(i + 1, 4)
        if k != i and k != j
    )
    if ok:
        nums.append(c)
print("count sets:", nums)

